"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";

export interface ChipProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Gekozen staat, bv. een actief filter. */
  selected?: boolean;
  icon?: React.ReactNode;
  /** Toont een kruisje; wordt aangeroepen bij klikken erop. */
  onRemove?: () => void;
  size?: "sm" | "md";
  /** Telling rechts in de chip. */
  count?: React.ReactNode;
}

/** Chip — klikbaar filterlabel; met `onRemove` wordt het een verwijderbare tag. */
export const Chip = React.forwardRef<HTMLButtonElement, ChipProps>(function Chip(
  { selected, icon, onRemove, size = "md", count, className, children, ...rest },
  ref
) {
  return (
    <button
      ref={ref}
      type="button"
      aria-pressed={selected}
      data-selected={selected ? "" : undefined}
      className={cn("lui-chip", `lui-chip-${size}`, className)}
      {...rest}
    >
      {icon && <span className="lui-chip-icon">{icon}</span>}
      {children}
      {count != null && <span className="lui-chip-count">{count}</span>}
      {onRemove && (
        <span
          role="button"
          tabIndex={-1}
          aria-label="Verwijderen"
          className="lui-chip-remove"
          onClick={(event) => {
            event.stopPropagation();
            onRemove();
          }}
        >
          <Icon name="x" size={12} strokeWidth={2.5} />
        </span>
      )}
    </button>
  );
});

export interface ChipGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Laat de chips op één regel scrollen in plaats van afbreken. */
  scrollable?: boolean;
}

/** ChipGroup — rij chips, bv. een filterbalk boven een lijst. */
export const ChipGroup = React.forwardRef<HTMLDivElement, ChipGroupProps>(function ChipGroup(
  { scrollable, className, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn("lui-chip-group", scrollable && "lui-chip-group-scroll", className)}
      {...rest}
    />
  );
});

/* ============================ Chip ============================ */
.lui-chip {
  display: inline-flex; align-items: center; gap: 6px;
  height: calc(30px * var(--density)); padding: 0 12px;
  border: 1px solid var(--border); border-radius: var(--r-full);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: 12.5px; font-weight: 600; white-space: nowrap;
  cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.lui-chip:hover { background: var(--surface-hover); color: var(--text); border-color: var(--border-strong); }
.lui-chip:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-chip:disabled { opacity: .5; cursor: not-allowed; }
.lui-chip[data-selected] {
  background: var(--accent-tint); color: var(--accent-active); border-color: var(--accent-border);
}
.lui-chip-icon { display: inline-flex; }
.lui-chip-icon svg { width: 14px; height: 14px; }
.lui-chip-count {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px;
  padding: 0 5px; border-radius: var(--r-full);
  background: var(--surface-3); color: var(--text-3);
  font-size: 10.5px; font-weight: 700;
}
.lui-chip[data-selected] .lui-chip-count { background: var(--accent-border); color: var(--accent-active); }
.lui-chip-remove {
  display: inline-grid; place-items: center; width: 16px; height: 16px;
  margin-right: -4px; border-radius: var(--r-full); color: var(--text-3);
}
.lui-chip-remove:hover { background: var(--surface-3); color: var(--text); }

.lui-chip-sm { height: 25px; padding: 0 9px; font-size: 11.5px; }

.lui-chip-group { display: flex; flex-wrap: wrap; gap: 7px; min-width: 0; }
.lui-chip-group-scroll {
  flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch;
  padding-bottom: 2px;
}
